import { z } from 'zod';
export { latestThemeVersions } from './latest-theme-versions.js';
export const createThemeVersionSchema = (latestVersion) => z
    .number()
    .int()
    .min(1)
    .max(latestVersion)
    .describe(`The version of the theme to use, from 1 to ${latestVersion}. Defaults to 1, the original version.`);
